{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title explicitly includes the phrase \"a systematic review and meta-analysis\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title identifies the population (\"children\") and the exposure/context (\"Post-ERCP adverse events\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title includes the analysis method (\"meta-analysis\") and the specific focus of the synthesis (\"postERCP pancreatitis incidence\", \"risk factors\", \"prevention strategies\")."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Endoscopic retrograde cholangiopancreatography (ERCP) is increasingly used in children with pancreatobiliary disease, but pediatric adverse-event estimates remain variable.",
      "reason": "The text describes the current state of knowledge (increasing use of ERCP in children) and the uncertainty (variable adverse-event estimates)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "We updated the evidence on post-ERCP adverse events in children, pooled post-ERCP pancreatitis (PEP) incidence when study-level data allowed, and summarized reported risk factors and prevention strategies.",
      "reason": "The authors explain the need for the review by stating their intent to update evidence, pool incidence data, and summarize risk factors and prevention strategies, addressing the variability mentioned in the background."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Prior systematic reviews and meta-analyses were used for background comparison and reference checking only.",
      "reason": "The authors acknowledge the existence of prior reviews and explain that they are using them for benchmarking rather than as primary data sources, thus explaining the need for the current updated review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of adverse events (observational data), not a review of intervention effects (e.g., a randomized controlled trial of a specific drug or device), so a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not evaluating a complex intervention or delivery context requiring a logic model; it is a systematic review of adverse event incidence and risk factors."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "While the title describes the scope of the review, the provided text does not contain an explicit statement of the review's objectives or research questions (e.g., 'The objective of this review was to...')."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on the incidence of adverse events (post-ERCP pancreatitis) and synthesis of risk factors/prevention strategies, rather than a comparative intervention effect study (e.g., comparing Intervention A vs. Intervention B), making a PICO framework not strictly applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Inclusion Criteria: Study Type: Original pediatric studies, including cohort studies, case-control studies, and randomized or nonrandomized interventional studies. Prior systematic reviews and meta-analyses were screened for contextual comparison and citation tracking only. Their pooled results were not entered into the present quantitative synthesis. Population: Pediatric patients (<18 years) undergoing ERCP. Outcomes: Reported incidence, types, risk factors, or management strategies of post-ERCP complications. Language: English. Publication Date: January 1, 2015 to June 26, 2025.",
      "reason": "The manuscript explicitly specifies the inclusion criteria, including study design, population, outcomes, language, and publication date."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Language: English. Publication Date: January 1, 2015 to June 26, 2025. ... Exclusion Criteria: ... Study Design: Case reports, narrative reviews, editorials, conference abstracts, animal studies, in vitro studies.",
      "reason": "The manuscript specifies eligibility criteria for report characteristics, including language, publication date, and publication status (excluding specific types like editorials and conference abstracts)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript lists 'Data Availability: Incomplete or unextractable data' as an exclusion criterion but does not distinguish between exclusion due to outcomes not being measured versus exclusion due to results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We prespecified subgroup exploration by age group, ERCP indication, procedure type, pancreatic duct manipulation or contrast injection, sphincterotomy, and operator or center volume. ... In the post hoc denominator-unit sensitivity summary, procedure-level studies contributed 181 PEP events among 2669 ERCPs (crude rate, 6.8%), patient-level or first-ERCP-per-child studies contributed 20 events among 421 children (4.8%), and the mixed or unclear-denominator study contributed 12 events among 232 observations (5.2%).",
      "reason": "The manuscript specifies how studies were grouped for synthesis, including subgroup analyses and grouping by denominator unit (procedure-level vs. patient-level)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The search was limited to studies published between January 1, 2015, and June 26, 2025, to capture contemporary pediatric ERCP practice, including changes in therapeutic indications, endoscopic accessories, anesthesia support, and prophylaxis strategies.",
      "reason": "The manuscript provides a clear rationale for the restriction on publication date."
    }
  ],
  "confidence": 100
}

